import {
  bindKeyFileStem,
  dnssecDs,
  dnssecKeyMatches,
  dnssecKeyTag,
  formatDs,
  generateDnssecKey,
  renderBindKeyFiles,
} from './dnssec';

describe('dnssec keys', () => {
  // Generated by bind's dnssec-keygen (9.20) for example.test.: tag 30591.
  const bindKey = {
    publicKey: 'rXRuV9OohaqjxO+CwYlbTZ9TSgHcurwLwybv0/V/YJs8/xYDnsyVWaEzfeHN9A0Bpq2eSFBtW36atZmXb+mstQ==',
    privateKey: '3ymD8rz6Q9ACynMlowawVrUkyfk3gIt3Ms/Ff1mLqog=',
  };

  it('computes key tags like bind', () => {
    expect(dnssecKeyTag(bindKey.publicKey)).toBe(30591);
    expect(bindKeyFileStem('example.test', bindKey.publicKey)).toBe('Kexample.test.+013+30591');
  });

  it('checks that a private key belongs to its public key', () => {
    const key = generateDnssecKey();

    expect(dnssecKeyMatches(key)).toBe(true);
    expect(dnssecKeyMatches(bindKey)).toBe(true);
    expect(dnssecKeyMatches({ ...key, privateKey: bindKey.privateKey })).toBe(false);
    expect(dnssecKeyMatches({ ...key, privateKey: 'AAAA' })).toBe(false);
  });

  it('derives the DS record (SHA-256 over owner name and DNSKEY)', () => {
    const ds = dnssecDs('Example.Test.', bindKey.publicKey);

    expect(ds).toMatchObject({ keyTag: 30591, algorithm: 13, digestType: 2 });
    expect(ds.digest).toMatch(/^[0-9A-F]{64}$/);
    expect(dnssecDs('example.test', bindKey.publicKey)).toEqual(ds);
    expect(formatDs('example.test', ds)).toBe(`example.test. IN DS 30591 13 2 ${ds.digest}`);
  });

  it('renders bind key files for a pregenerated CSK', () => {
    const files = renderBindKeyFiles('example.test', bindKey, {
      created: new Date('2026-10-17T16:54:16Z'),
      retired: new Date('2027-10-17T00:00:00Z'),
    });

    expect(files.key).toContain(`example.test. 3600 IN DNSKEY 257 3 13 ${bindKey.publicKey}`);
    expect(files.private).toContain(`PrivateKey: ${bindKey.privateKey}`);
    expect(files.private).toContain('Activate: 20261017165416');
    expect(files.state).toContain('KSK: yes\nZSK: yes');
    expect(files.state).toContain('Generated: 20261017165416 (Sat Oct 17 16:54:16 2026)');
    expect(files.state).toContain('Retired: 20271017000000');
  });
});
